<?php
require dirname(__DIR__).'/includes/bootstrap.php';require_admin();require __DIR__.'/_layout.php';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_token();$id=(int)($_POST['id']??0);$action=$_POST['action']??'';if($id>0 && in_array($action,['read','delete'],true)){$sql=$action==='read'?'UPDATE messages SET is_read=1 WHERE id=?':'DELETE FROM messages WHERE id=?';$stmt=db()->prepare($sql);$stmt->execute([$id]);flash('success','Inbox updated.');}redirect('admin/messages.php');}
$messages=db()->query('SELECT * FROM messages ORDER BY created_at DESC LIMIT 200')->fetchAll();admin_header('Contact inbox');?><div class="toolbar"><p>Latest 200 contact messages. Email replies can be sent from your preferred email provider.</p></div><div class="message-list"><?php foreach($messages as $m): ?><article class="message-card <?= !$m['is_read']?'unread':'' ?>"><div class="message-head"><div><span class="message-date"><?= e($m['created_at']) ?></span><h2><?= e($m['subject']) ?></h2><p><?= e($m['sender_name']) ?> · <a href="mailto:<?= e($m['sender_email']) ?>"><?= e($m['sender_email']) ?></a></p></div><div class="actions"><?php if(!$m['is_read']): ?><form method="post"><input type="hidden" name="csrf" value="<?= e(token()) ?>"><input type="hidden" name="id" value="<?= (int)$m['id'] ?>"><input type="hidden" name="action" value="read"><button>Mark read</button></form><?php endif; ?><form method="post" onsubmit="return confirm('Delete this message?')"><input type="hidden" name="csrf" value="<?= e(token()) ?>"><input type="hidden" name="id" value="<?= (int)$m['id'] ?>"><input type="hidden" name="action" value="delete"><button>Delete</button></form></div></div><p class="message-text"><?= nl2br(e($m['message'])) ?></p></article><?php endforeach; ?><?php if(!$messages): ?><div class="admin-panel"><p>No contact messages yet.</p></div><?php endif; ?></div><?php admin_footer(); ?>
